// edge-keeping blur: neighbours of a like colour mix, a strong edge stays
const R = 8 / 1600
const smooth = (read: (uv: vec2) => vec4, uv: vec2) => {
  const c0 = read(uv)
  let sum = vec4(0)
  let w = 0
  for (let y = -3; y <= 3; y++) {
    for (let x = -3; x <= 3; x++) {
      const c = read(vec2(uv + vec2(x, y) * (R * res.x / 3) / res))
      const d = vec4(c - c0)
      const k = exp(0 - dot(d.rgb, d.rgb) / 0.0081 - (x * x + y * y) / 5.4)
      sum = vec4(sum + c * k)
      w = w + k
    }
  }
  return vec4(sum / w)
}
const soft1: Buffer = buffer({ once: true }, q => smooth(uv => scene.sample(uv), q.uv))
const soft2: Buffer = buffer({ once: true }, q => smooth(uv => soft1.sample(uv), q.uv))

// a zigzag field of a packed int as a whole number from -31 to 31
const field = (v: int, shift: number) => {
  const z = int((v >> shift) & 63)
  return signed(int((z >> 1) ^ (0 - (z & 1))))
}

export default shader({
  fps: 30,
  passes: [soft1, soft2, picture(q => {
    // the window shows the picture centred and cropped to fill (like the Svg's slice)
    const aspect = size.x / size.y
    const fx = min(1, aspect / 1.68421)
    const fy = min(1, 1.68421 / aspect)
    const pic = vec2(0.5 + (q.uv.x - 0.5) * fx, 0.5 + (0.5 - q.uv.y) * fy)
    const gu = clamp(pic.x * 24 - 0.5, 0, 23)
    const gv = clamp(pic.y * 14 - 0.5, 0, 13)
    const i0 = min(floor(gu), 22)
    const j0 = min(floor(gv), 12)
    const fu = gu - i0
    const fv = gv - j0
    const ph = time * 0.785398
    const c1 = cos(ph) - 1
    const s1 = sin(ph)
    const c2 = cos(ph * 2) - 1
    const s2 = sin(ph * 2)
    const c3 = cos(ph * 3) - 1
    const s3 = sin(ph * 3)
    let dx = 0
    let dy = 0
    for (const [di, dj, wt] of [[0, 0, (1 - fu) * (1 - fv)], [1, 0, fu * (1 - fv)], [0, 1, (1 - fu) * fv], [1, 1, fu * fv]] as const) {
      const n = (j0 + dj) * 24 + i0 + di
      const a = A.at(n)
      const b = B.at(n - 168)
      const h1 = n < 168 ? a[0] : b[0]
      const h2 = n < 168 ? a[1] : b[1]
      const h3 = n < 168 ? a[2] : b[2]
      dx = dx + wt * ((field(h1, 18) * c1 + field(h1, 12) * s1) * 0.001293 + (field(h2, 18) * c2 + field(h2, 12) * s2) * 0.001052 + (field(h3, 18) * c3 + field(h3, 12) * s3) * 0.0008169)
      dy = dy + wt * ((field(h1, 6) * c1 + field(h1, 0) * s1) * 0.002178 + (field(h2, 6) * c2 + field(h2, 0) * s2) * 0.001771 + (field(h3, 6) * c3 + field(h3, 0) * s3) * 0.001376)
    }
    // the pixel shows the picture where that bit of it was at the start (Reduce Motion holds it still)
    const move = 1 - still
    const from = vec2(q.uv.x - dx * move / fx, q.uv.y + dy * move / fy)
    return vec4(soft2.sample(from).rgb, 1)
  })],
})
